type SystemMessage = {
    role: 'system';
    content: string;
};
type UserMessage = {
    role: 'user';
    content: string;
};
type AssistantMessage = {
    role: 'assistant';
    content: string;
};
type ToolMessage = {
    role: 'tool';
    content: string;
    tool_call_id: string;
};
type LingYiMessage = SystemMessage | UserMessage | AssistantMessage | ToolMessage;
export type LingYiInputData = {
    model: string;
    messages: Array<LingYiMessage>;
    tools?: Array<{
        type: 'function';
        function: {
            name: string;
            description?: string;
            parameters: object;
        };
    }>;
    tool_choice?: string | object;
    max_tokens?: number | null;
    top_p?: number;
    temperature?: number;
};
export type LingYiGenerateTextOutput = {
    choices?: Array<{
        message?: {
            content?: string;
        };
    }>;
};
export type LingYiStreamTextOutput = {
    choices?: Array<{
        delta?: {
            content?: string;
        };
    }>;
};
export {};
